import cgi
import http.server
import json

SUCCESS_RESPONSE = {'status': 'success', 'message': 'Data received successfully.'}
ERROR_RESPONSE = {'status': 'error', 'message': 'Invalid data received.'}


def task_func(data=None):
    """
    Creates and returns an HTTP POST request handler class that validates
    incoming JSON data.

    The handler:
    - Checks Content-Type header is 'application/json' (400 if not)
    - Parses JSON body (400 if malformed)
    - Checks for 'data' key in JSON object (400 if missing)
    - Returns 200 with success message if all validations pass

    Returns:
        A class (subclass of http.server.BaseHTTPRequestHandler) with
        do_POST method implemented.
    """

    class PostRequestHandler(http.server.BaseHTTPRequestHandler):

        def do_POST(self):
            content_type = self.headers.get('Content-Type', '')

            if content_type != 'application/json':
                self._send_response(
                    400,
                    {**ERROR_RESPONSE, 'message': 'Content-Type header is not application/json'}
                )
                return

            content_length = int(self.headers.get('Content-Length', 0))
            raw_body = self.rfile.read(content_length)

            try:
                parsed = json.loads(raw_body.decode('utf-8'))
            except (json.JSONDecodeError, ValueError):
                self._send_response(
                    400,
                    {**ERROR_RESPONSE, 'message': 'Invalid JSON'}
                )
                return

            if 'data' not in parsed:
                self._send_response(
                    400,
                    {**ERROR_RESPONSE, 'message': 'No data key in request'}
                )
                return

            self._send_response(200, SUCCESS_RESPONSE)

        def _send_response(self, status_code, response_dict):
            response_body = json.dumps(response_dict).encode('utf-8')
            self.send_response(status_code)
            self.send_header('Content-Type', 'application/json')
            self.send_header('Content-Length', str(len(response_body)))
            self.end_headers()
            self.wfile.write(response_body)

        def log_message(self, format, *args):
            pass

    return PostRequestHandler
